<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import {emptyRulesV2} from './api-v2'
import UiButton from '@/components/ui/UiButton.vue'
import UiSelectField from '@/components/ui/UiSelectField.vue'
import ModelRuleFields from './ModelRuleFields.vue'
import {useModelsV2Store} from './store-v2'
import {originLabelV2,type ChannelV2,type EffectiveModelV2,type ModelEditV2,type ModelSelectionV2,type RulesV2,type ChannelIntentV2} from './api-v2'
import type {ChannelPolicy,ModelPolicy,ModelProjection} from './api'
import type {ModelRowsState} from './modelRows'
const props=defineProps<{channel:ChannelV2|ChannelPolicy;effective?:readonly EffectiveModelV2[];disabled?:boolean;query?:string;selectedOnly?:boolean;models?:readonly unknown[];templates?:readonly unknown[];policy?:ModelPolicy;projection?:ModelProjection[];projectionBusy?:boolean;filtered?:boolean;state?:ModelRowsState}>()
const emit=defineEmits<{edit:[value:ModelEditV2];selection:[value:ModelSelectionV2];order:[ids:string[]];intent:[value:ChannelIntentV2]}>()
const store=useModelsV2Store(),expanded=ref<string|null>(null),batchIds=ref<string[]>([]),batchOpen=ref(false),batchRules=ref(emptyRulesV2()),batchModes=ref<Record<string,'keep'|'inherit'|'custom'>>({}),batchError=ref('')
let batchBaseline=''
const batchFields=[['protocol','请求协议'],['contextWindow','上下文'],['inputModalities','输入模态'],['reasoningEfforts','推理档位'],['defaultEffort','默认档位'],['fast','Fast'],['pinnedEffort','强制档'],['effortMap','档位映射'],['noReasoning','不传推理参数'],['reasoningAuthoritative','推理权威'],['fastWire','Fast wire']] as const
const channel=computed(()=>('models'in props.channel?props.channel:null) as ChannelV2|null)
const selected=(id:string)=>channel.value?.selection.mode==='all'||channel.value?.selection.mode==='whitelist'&&channel.value.selection.models.includes(id)
const ordered=computed(()=>{const c=channel.value;if(!c)return [];const rank=new Map(c.modelOrder.map((id,index)=>[id,index]));return [...c.models].sort((a,b)=>(rank.get(a.rawModelId)??c.models.length)-(rank.get(b.rawModelId)??c.models.length))})
const rows=computed(()=>ordered.value.filter(m=>(!props.selectedOnly||selected(m.rawModelId))&&(!props.query||(m.rawModelId+' '+m.label).toLowerCase().includes(props.query.toLowerCase()))))
const effective=(id:string)=>props.effective?.find(row=>row.channelId===props.channel.id&&row.rawModelId===id)
function toggle(id:string,checked:boolean){if(props.disabled||!channel.value)return;const ids=ordered.value.filter(m=>selected(m.rawModelId)).map(m=>m.rawModelId);emit('selection',{mode:'whitelist',models:checked?[...new Set([...ids,id])]:ids.filter(value=>value!==id)})}
function updateRules(id:string,next:RulesV2){if(props.disabled)return;const before=store.explicitRules(props.channel.id,id);for(const field of Object.keys(next) as (keyof RulesV2)[]){const value=next[field];if(JSON.stringify(value??{mode:'inherit'})===JSON.stringify(before[field]??{mode:'inherit'}))continue;if(!value||value.mode==='inherit')emit('edit',{kind:'clear_override',channelId:props.channel.id,rawModelId:id,field});else emit('edit',{kind:'set_override',channelId:props.channel.id,rawModelId:id,field,value:value.value})}}
function move(id:string,delta:number){if(props.disabled||props.query||props.selectedOnly||props.filtered)return;const ids=ordered.value.map(m=>m.rawModelId),at=ids.indexOf(id),to=at+delta;if(at<0||to<0||to>=ids.length)return;[ids[at],ids[to]]=[ids[to]!,ids[at]!];emit('order',ids)}
function protocolText(id:string){const p=effective(id)?.protocol;return !p?'尚未核对':p.kind==='resolved'?p.value:p.kind==='missing'?'待配置':p.value+' · 暂不支持'}
function naming(rawModelId:string,field:'alias'|'displayName',value:string){if(props.disabled||!channel.value||!store.channelCapabilities.naming)return;const current=channel.value.naming[rawModelId]??{};emit('intent',{kind:'set_naming',channelId:channel.value.id,rawModelId,alias:field==='alias'?(value||null):(current.alias??null),displayName:field==='displayName'?(value||null):(current.displayName??null)})}
function bindingValue(rawModelId:string){const edit=store.modelEdits.find(e=>e.channelId===props.channel.id&&e.rawModelId===rawModelId&&(e.kind==='set_manual_binding'||e.kind==='clear_manual_binding'));if(edit?.kind==='clear_manual_binding')return '';const reference=edit?.kind==='set_manual_binding'?edit.reference:channel.value?.models.find(m=>m.rawModelId===rawModelId)?.binding?.reference;return reference?reference.templateId+'|'+reference.revisionId:''}
function bind(rawModelId:string,value:string){if(props.disabled)return;if(!value){emit('edit',{kind:'clear_manual_binding',channelId:props.channel.id,rawModelId});return}for(const template of store.file?.library.templates??[]){const revision=template.revisions.find(r=>template.id+'|'+r.id===value);if(revision){emit('edit',{kind:'set_manual_binding',channelId:props.channel.id,rawModelId,reference:{templateId:template.id,revisionId:revision.id,digest:revision.digest}});return}}}
function openBatch(){batchBaseline=JSON.stringify({channel:props.channel,edits:store.modelEdits});batchModes.value=Object.fromEntries(batchFields.map(([key])=>[key,'keep']));batchRules.value=emptyRulesV2();batchError.value='';batchOpen.value=true}
function applyBatch(){if(props.disabled)return;if(batchBaseline!==JSON.stringify({channel:props.channel,edits:store.modelEdits})){batchError.value='批量确认已过期，请重新选择；当前输入保持。';return}const edits:ModelEditV2[]=[];for(const id of batchIds.value){if(!channel.value?.models.some(m=>m.rawModelId===id)){batchError.value='所选模型已变化，未应用本次批量。';return}for(const [field,label] of batchFields){const mode=batchModes.value[field]??'keep';if(mode==='keep')continue;if(mode==='inherit'){edits.push({kind:'clear_override',channelId:props.channel.id,rawModelId:id,field});continue}const value=batchRules.value[field];if(!value||value.mode!=='custom'){batchError.value='请填写 '+label+' 的明确自定义值，未应用任何项。';return}edits.push({kind:'set_override',channelId:props.channel.id,rawModelId:id,field,value:value.value})}}if(!edits.length){batchError.value='未选择需要修改的字段。';return}for(const edit of edits)emit('edit',edit);batchOpen.value=false}
watch(()=>props.channel.id,()=>{batchIds.value=[];batchOpen.value=false;expanded.value=null})
</script>
<template>
  <div class="channel-model-table-v2">
    <p v-if="!channel" role="alert" class="model-error">渠道格式暂不支持，请重新读取新版渠道；未转换旧配置。</p>
    <template v-else>
      <p class="model-muted">勾选控制公开范围；配置只记录明确人工编辑。当前有效值来自服务端快照，未保存编辑不冒充已生效。</p>
      <div class="model-inline"><span>批量操作已选 {{batchIds.length}} 项（独立于公开范围）</span><UiButton size="sm" :disabled="disabled||!batchIds.length" @click="openBatch">批量配置所选模型</UiButton><UiButton size="sm" :disabled="!batchIds.length" @click="batchIds=[]">清空操作选择</UiButton></div>
      <div class="model-table-scroll"><table class="model-table"><thead><tr><th>操作选择</th><th>公开</th><th>模型</th><th>请求协议与来源</th><th>配置与顺序</th></tr></thead><tbody>
        <template v-for="(model,index) in rows" :key="model.rawModelId">
          <tr><td><input v-model="batchIds" type="checkbox" :value="model.rawModelId" :aria-label="'批量选择模型 '+model.rawModelId" :disabled="disabled" /></td><td><input type="checkbox" :aria-label="'公开模型 '+model.rawModelId" :checked="selected(model.rawModelId)" :disabled="disabled" @change="toggle(model.rawModelId,($event.target as HTMLInputElement).checked)" /></td><td><strong>{{model.label||model.rawModelId}}</strong><code>{{model.rawModelId}}</code><small>{{model.observed?'已观察到':'手工/已保存 ID，未要求先发现'}}</small></td><td><span>{{protocolText(model.rawModelId)}}</span><small>{{originLabelV2(effective(model.rawModelId)?.fieldOrigins.protocol)}}</small><small v-if="model.binding">{{model.binding.kind==='manual'?'人工指定模版':'读取自动匹配'}} · {{model.binding.reference.revisionId}}</small></td><td><div class="model-inline"><UiButton size="sm" :aria-expanded="expanded===model.rawModelId" @click="expanded=expanded===model.rawModelId?null:model.rawModelId">配置</UiButton><UiButton size="sm" :disabled="disabled||!!query||selectedOnly||filtered||index===0" @click="move(model.rawModelId,-1)">上移</UiButton><UiButton size="sm" :disabled="disabled||!!query||selectedOnly||filtered||index===rows.length-1" @click="move(model.rawModelId,1)">下移</UiButton></div></td></tr>
          <tr v-if="expanded===model.rawModelId"><td colspan="5"><h3>单模型人工设置 · {{model.rawModelId}}</h3><div class="model-columns"><label>别名<input class="input" :aria-label="model.rawModelId+'别名'" :value="channel.naming[model.rawModelId]?.alias??''" :disabled="disabled||!store.channelCapabilities.naming" @input="naming(model.rawModelId,'alias',($event.target as HTMLInputElement).value)" /></label><label>显示名称<input class="input" :aria-label="model.rawModelId+'显示名称'" :value="channel.naming[model.rawModelId]?.displayName??''" :disabled="disabled||!store.channelCapabilities.naming" @input="naming(model.rawModelId,'displayName',($event.target as HTMLInputElement).value)" /></label><label>人工指定模版<UiSelectField :model-value="bindingValue(model.rawModelId)" :label="model.rawModelId+'人工模版'" :disabled="disabled" :options="[{value:'',label:'不作人工指定'},...(store.file?.library.templates??[]).flatMap(t=>t.revisions.map(r=>({value:t.id+'|'+r.id,label:t.label+' · '+r.id.slice(0,8)})))]" @update:model-value="bind(model.rawModelId,$event)" /></label></div><ModelRuleFields :model-value="store.explicitRules(channel.id,model.rawModelId)" :effective-v2="effective(model.rawModelId)" :disabled="disabled" @update:model-value="updateRules(model.rawModelId,$event)" /><details><summary>实际来源证据与精确模版引用</summary><dl><template v-for="(field,key) in model.source.fields" :key="key"><dt>{{key}}</dt><dd>{{field.evidence.kind}} · {{field.evidence.pointer}} · {{field.evidence.sourceDigest}}</dd></template></dl><p v-if="model.binding">{{model.binding.reference.templateId}} / {{model.binding.reference.revisionId}} / {{model.binding.reference.digest}}</p><p v-else>未引用保存模版。</p></details></td></tr>
        </template>
      </tbody></table></div>
      <UiDialog :open="batchOpen" title="批量配置明确字段" wide @close="batchOpen=false"><p>本次只修改以下 {{batchIds.length}} 个精确 ID 的明确字段；未选模型、原始 ID、来源值与顺序保持。</p><p>{{batchIds.join('、')}}</p><div class="model-columns"><label v-for="[field,label] in batchFields" :key="field">{{label}}<UiSelectField :model-value="batchModes[field]??'keep'" :label="'批量'+label+'处理方式'" :disabled="disabled" :options="[{value:'keep',label:'保持原值'},{value:'inherit',label:'恢复继承'},{value:'custom',label:'明确自定义'}]" @update:model-value="batchModes[field]=$event as 'keep'|'inherit'|'custom'" /></label></div><ModelRuleFields v-model="batchRules" :disabled="disabled" /><p v-if="batchError" role="alert" class="model-error">{{batchError}}</p><template #actions="{close}"><UiButton @click="close">取消</UiButton><UiButton variant="primary" :disabled="disabled" @click="applyBatch">确认批量加入编辑</UiButton></template></UiDialog>
      <p v-if="!rows.length" class="model-muted">当前筛选下没有模型；不会清空原始 ID 或配置。</p>
    </template>
  </div>
</template>
<style scoped>
.channel-model-table-v2{min-width:0}.channel-model-table-v2 .model-table-scroll{overflow:auto}.channel-model-table-v2 table{width:100%;min-width:580px}.channel-model-table-v2 th,.channel-model-table-v2 td{padding:10px;text-align:left;vertical-align:top;border-bottom:1px solid var(--border)}.channel-model-table-v2 code,.channel-model-table-v2 small{display:block;overflow-wrap:anywhere;color:var(--muted)}.channel-model-table-v2 dd{margin:0;overflow-wrap:anywhere}.channel-model-table-v2 h3{font-size:var(--text-body)}
</style>
